 17→// Ensure FactoryAIDroidAgent implements HookSupport
 18→var _ agent.HookSupport = (*FactoryAIDroidAgent)(nil)
 19→
 20→// Factory AI Droid hook names - these become subcommands under `entire hooks factoryai-droid`
 21→const (
 22→	HookNameSessionStart     = "session-start"
 23→	HookNameSessionEnd       = "session-end"
 24→	HookNameStop             = "stop"
 25→	HookNameUserPromptSubmit = "user-prompt-submit"
 26→	HookNamePreToolUse       = "pre-tool-use"
 27→	HookNamePostToolUse      = "post-tool-use"
 28→	HookNameSubagentStop     = "subagent-stop"
 29→	HookNamePreCompact       = "pre-compact"
 30→	HookNameNotification     = "notification"
 31→)
