 33→// FactorySettingsFileName is the settings file used by Factory AI Droid.
 34→// This is Factory-specific and not shared with other agents.
 35→const FactorySettingsFileName = "settings.json"
 36→
 37→// metadataDenyRule blocks Factory Droid from reading Entire session metadata
 38→const metadataDenyRule = "Read(./.entire/metadata/**)"
 39→
 40→// entireHookPrefixes are command prefixes that identify Entire hooks (both old and new formats)
 41→var entireHookPrefixes = []string{
 42→	"entire ",
 43→	"go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go ",
 44→}
