 46→// InstallHooks installs Factory AI Droid hooks in .factory/settings.json.
 47→// If force is true, removes existing Entire hooks before installing.
 48→// Returns the number of hooks installed.
 49→func (f *FactoryAIDroidAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 50→	// Use repo root instead of CWD to find .factory directory
 51→	// This ensures hooks are installed correctly when run from a subdirectory
 52→	repoRoot, err := paths.WorktreeRoot(ctx)
 53→	if err != nil {
 54→		// Fallback to CWD if not in a git repo (e.g., during tests)
 55→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
 56→		if err != nil {
 57→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 58→		}
 59→	}
 60→
 61→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
 62→
 63→	// Read existing settings if they exist
 64→	var rawSettings map[string]json.RawMessage
 65→
 66→	// rawHooks preserves unknown hook types
 67→	var rawHooks map[string]json.RawMessage
 68→
 69→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 70→	var rawPermissions map[string]json.RawMessage
 71→
 72→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
 73→	if readErr == nil {
 74→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 75→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 76→		}
 77→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 78→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 79→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 80→			}
 81→		}
 82→		if permRaw, ok := rawSettings["permissions"]; ok {
 83→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
 84→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
 85→			}
 86→		}
 87→	} else {
 88→		rawSettings = make(map[string]json.RawMessage)
 89→	}
 90→
 91→	if rawHooks == nil {
 92→		rawHooks = make(map[string]json.RawMessage)
 93→	}
 94→	if rawPermissions == nil {
 95→		rawPermissions = make(map[string]json.RawMessage)
 96→	}
 97→
 98→	// Parse only the hook types we need to modify
 99→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
100→	parseHookType(rawHooks, "SessionStart", &sessionStart)
101→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
102→	parseHookType(rawHooks, "Stop", &stop)
103→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
104→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
105→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
106→	parseHookType(rawHooks, "PreCompact", &preCompact)
107→
108→	// If force is true, remove all existing Entire hooks first
109→	if force {
110→		sessionStart = removeEntireHooks(sessionStart)
111→		sessionEnd = removeEntireHooks(sessionEnd)
112→		stop = removeEntireHooks(stop)
113→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
114→		preToolUse = removeEntireHooks(preToolUse)
115→		postToolUse = removeEntireHooks(postToolUse)
116→		preCompact = removeEntireHooks(preCompact)
117→	}
118→
119→	// Define hook commands
120→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
121→	if localDev {
122→		sessionStartCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-start"
123→		sessionEndCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-end"
124→		stopCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid stop"
125→		userPromptSubmitCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid user-prompt-submit"
126→		preTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-tool-use"
127→		postTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid post-tool-use"
128→		preCompactCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-compact"
129→	} else {
130→		sessionStartCmd = "entire hooks factoryai-droid session-start"
131→		sessionEndCmd = "entire hooks factoryai-droid session-end"
132→		stopCmd = "entire hooks factoryai-droid stop"
133→		userPromptSubmitCmd = "entire hooks factoryai-droid user-prompt-submit"
134→		preTaskCmd = "entire hooks factoryai-droid pre-tool-use"
135→		postTaskCmd = "entire hooks factoryai-droid post-tool-use"
136→		preCompactCmd = "entire hooks factoryai-droid pre-compact"
137→	}
138→
139→	count := 0
140→
141→	// Add hooks if they don't exist
142→	if !hookCommandExists(sessionStart, sessionStartCmd) {
143→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
144→		count++
145→	}
146→	// Also install user-prompt-submit on SessionStart to ensure TurnStart fires
147→	// even when UserPromptSubmit doesn't (e.g., droid exec mode).
148→	// The user-prompt-submit handler gracefully handles SessionStart's stdin format
149→	// (userPromptSubmitRaw is a superset of sessionInfoRaw; Prompt defaults to "").
150→	if !hookCommandExists(sessionStart, userPromptSubmitCmd) {
151→		sessionStart = addHookToMatcher(sessionStart, "", userPromptSubmitCmd)
152→		count++
153→	}
154→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
155→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
156→		count++
157→	}
158→	if !hookCommandExists(stop, stopCmd) {
159→		stop = addHookToMatcher(stop, "", stopCmd)
160→		count++
161→	}
162→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
163→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
164→		count++
165→	}
166→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
167→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
168→		count++
169→	}
170→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
171→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
172→		count++
173→	}
174→	if !hookCommandExists(preCompact, preCompactCmd) {
175→		preCompact = addHookToMatcher(preCompact, "", preCompactCmd)
176→		count++
177→	}
178→
179→	// Add permissions.deny rule if not present
180→	permissionsChanged := false
181→	var denyRules []string
182→	if denyRaw, ok := rawPermissions["deny"]; ok {
183→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
184→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
185→		}
186→	}
187→	if !slices.Contains(denyRules, metadataDenyRule) {
188→		denyRules = append(denyRules, metadataDenyRule)
189→		denyJSON, err := json.Marshal(denyRules)
190→		if err != nil {
191→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
192→		}
193→		rawPermissions["deny"] = denyJSON
194→		permissionsChanged = true
195→	}
196→
197→	if count == 0 && !permissionsChanged {
198→		return 0, nil // All hooks and permissions already installed
199→	}
200→
201→	// Marshal modified hook types back to rawHooks
202→	marshalHookType(rawHooks, "SessionStart", sessionStart)
203→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
204→	marshalHookType(rawHooks, "Stop", stop)
205→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
206→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
207→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
208→	marshalHookType(rawHooks, "PreCompact", preCompact)
209→
210→	// Marshal hooks and update raw settings
211→	hooksJSON, err := json.Marshal(rawHooks)
212→	if err != nil {
213→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
214→	}
215→	rawSettings["hooks"] = hooksJSON
216→
217→	// Marshal permissions and update raw settings
218→	permJSON, err := json.Marshal(rawPermissions)
219→	if err != nil {
220→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
221→	}
222→	rawSettings["permissions"] = permJSON
223→
224→	// Write back to file
225→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
226→		return 0, fmt.Errorf("failed to create .factory directory: %w", err)
227→	}
228→
229→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
230→	if err != nil {
231→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
232→	}
233→
234→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
235→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
236→	}
237→
238→	return count, nil
239→}
