264→// UninstallHooks removes Entire hooks from Factory AI Droid settings.
265→func (f *FactoryAIDroidAgent) UninstallHooks(ctx context.Context) error {
266→	// Use repo root to find .factory directory when run from a subdirectory
267→	repoRoot, err := paths.WorktreeRoot(ctx)
268→	if err != nil {
269→		repoRoot = "." // Fallback to CWD if not in a git repo
270→	}
271→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
272→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
273→	if err != nil {
274→		return nil //nolint:nilerr // No settings file means nothing to uninstall
275→	}
276→
277→	var rawSettings map[string]json.RawMessage
278→	if err := json.Unmarshal(data, &rawSettings); err != nil {
279→		return fmt.Errorf("failed to parse settings.json: %w", err)
280→	}
281→
282→	// rawHooks preserves unknown hook types
283→	var rawHooks map[string]json.RawMessage
284→	if hooksRaw, ok := rawSettings["hooks"]; ok {
285→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
286→			return fmt.Errorf("failed to parse hooks: %w", err)
287→		}
288→	}
289→	if rawHooks == nil {
290→		rawHooks = make(map[string]json.RawMessage)
291→	}
292→
293→	// Parse only the hook types we need to modify
294→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
295→	parseHookType(rawHooks, "SessionStart", &sessionStart)
296→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
297→	parseHookType(rawHooks, "Stop", &stop)
298→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
299→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
300→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
301→	parseHookType(rawHooks, "PreCompact", &preCompact)
302→
303→	// Remove Entire hooks from all hook types
304→	sessionStart = removeEntireHooks(sessionStart)
305→	sessionEnd = removeEntireHooks(sessionEnd)
306→	stop = removeEntireHooks(stop)
307→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
308→	preToolUse = removeEntireHooks(preToolUse)
309→	postToolUse = removeEntireHooks(postToolUse)
310→	preCompact = removeEntireHooks(preCompact)
311→
312→	// Marshal modified hook types back to rawHooks
313→	marshalHookType(rawHooks, "SessionStart", sessionStart)
314→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
315→	marshalHookType(rawHooks, "Stop", stop)
316→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
317→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
318→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
319→	marshalHookType(rawHooks, "PreCompact", preCompact)
320→
321→	// Also remove the metadata deny rule from permissions
322→	var rawPermissions map[string]json.RawMessage
323→	if permRaw, ok := rawSettings["permissions"]; ok {
324→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
325→			// If parsing fails, just skip permissions cleanup
326→			rawPermissions = nil
327→		}
328→	}
329→
330→	if rawPermissions != nil {
331→		if denyRaw, ok := rawPermissions["deny"]; ok {
332→			var denyRules []string
333→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
334→				// Filter out the metadata deny rule
335→				filteredRules := make([]string, 0, len(denyRules))
336→				for _, rule := range denyRules {
337→					if rule != metadataDenyRule {
338→						filteredRules = append(filteredRules, rule)
339→					}
340→				}
341→				if len(filteredRules) > 0 {
342→					denyJSON, err := json.Marshal(filteredRules)
343→					if err == nil {
344→						rawPermissions["deny"] = denyJSON
345→					}
346→				} else {
347→					// Remove empty deny array
348→					delete(rawPermissions, "deny")
349→				}
350→			}
351→		}
352→
353→		// If permissions is empty, remove it entirely
354→		if len(rawPermissions) > 0 {
355→			permJSON, err := json.Marshal(rawPermissions)
356→			if err == nil {
357→				rawSettings["permissions"] = permJSON
358→			}
359→		} else {
360→			delete(rawSettings, "permissions")
361→		}
362→	}
363→
364→	// Marshal hooks back (preserving unknown hook types)
365→	if len(rawHooks) > 0 {
366→		hooksJSON, err := json.Marshal(rawHooks)
367→		if err != nil {
368→			return fmt.Errorf("failed to marshal hooks: %w", err)
369→		}
370→		rawSettings["hooks"] = hooksJSON
371→	} else {
372→		delete(rawSettings, "hooks")
373→	}
374→
375→	// Write back
376→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
377→	if err != nil {
378→		return fmt.Errorf("failed to marshal settings: %w", err)
379→	}
380→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
381→		return fmt.Errorf("failed to write settings.json: %w", err)
382→	}
383→	return nil
384→}
