 24→// WriteHookResponse outputs the hook response as plain text to stdout.
 25→// Factory AI Droid does not parse the JSON systemMessage protocol,
 26→// so we write plain text that it displays directly in the terminal.
 27→func (f *FactoryAIDroidAgent) WriteHookResponse(message string) error {
 28→	if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
 29→		return fmt.Errorf("failed to write hook response: %w", err)
 30→	}
 31→	return nil
 32→}
