 50→// ParseHookEvent translates a Factory AI Droid hook into a normalized lifecycle Event.
 51→// Returns nil if the hook has no lifecycle significance.
 52→func (f *FactoryAIDroidAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 53→	switch hookName {
 54→	case HookNameSessionStart:
 55→		return f.parseSessionStart(stdin)
 56→	case HookNameUserPromptSubmit:
 57→		return f.parseTurnStart(stdin)
 58→	case HookNameStop:
 59→		return f.parseTurnEnd(stdin)
 60→	case HookNameSessionEnd:
 61→		return f.parseSessionEnd(stdin)
 62→	case HookNamePreToolUse:
 63→		return f.parseSubagentStart(stdin)
 64→	case HookNamePostToolUse:
 65→		return f.parseSubagentEnd(stdin)
 66→	case HookNamePreCompact:
 67→		return f.parseCompaction(stdin)
 68→	case HookNameSubagentStop, HookNameNotification:
 69→		// Acknowledged hooks with no lifecycle action
 70→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 71→	default:
 72→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 73→	}
 74→}
