 83→func (d *Droid) Bootstrap() error {
 84→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 85→	if apiKey == "" {
 86→		return nil
 87→	}
 88→
 89→	home, err := os.UserHomeDir()
 90→	if err != nil {
 91→		return fmt.Errorf("get home dir: %w", err)
 92→	}
 93→	dir := filepath.Join(home, ".factory")
 94→	if err := os.MkdirAll(dir, 0o755); err != nil {
 95→		return fmt.Errorf("mkdir %s: %w", dir, err)
 96→	}
 97→
 98→	settingsPath := filepath.Join(dir, "settings.json")
 99→
100→	// Read existing settings to merge (hooks may already be configured
101→	// in the repo-local .factory/settings.json, but the global config
102→	// at ~/.factory/settings.json might have other pre-existing entries).
103→	var settings droidSettings
104→	if data, readErr := os.ReadFile(settingsPath); readErr == nil {
105→		// Best-effort merge: ignore parse errors and start fresh
106→		_ = json.Unmarshal(data, &settings)
107→	}
108→
109→	// Replace or add the BYOK model entry.
110→	byokModel := droidCustomModel{
111→		DisplayName:    droidCustomModelDisplayName,
112→		Model:          droidCustomModelBaseID,
113→		BaseURL:        "https://api.anthropic.com",
114→		APIKey:         apiKey,
115→		Provider:       "anthropic",
116→		MaxOutputToken: 8192,
117→	}
118→
119→	found := false
120→	for i, m := range settings.CustomModels {
121→		if m.Model == byokModel.Model {
122→			settings.CustomModels[i] = byokModel
123→			found = true
124→			break
125→		}
126→	}
127→	if !found {
128→		settings.CustomModels = append(settings.CustomModels, byokModel)
129→	}
130→
131→	data, err := json.MarshalIndent(settings, "", "  ")
132→	if err != nil {
133→		return fmt.Errorf("marshal settings: %w", err)
134→	}
135→	return os.WriteFile(settingsPath, data, 0o644)
136→}
