715→// splitPromptContent splits prompt.txt content on the "\n\n---\n\n" separator.
716→// Returns nil if content is empty.
717→func splitPromptContent(content string) []string {
718→	if content == "" {
719→		return nil
720→	}
721→	parts := strings.Split(content, "\n\n---\n\n")
722→	var result []string
723→	for _, p := range parts {
724→		trimmed := strings.TrimSpace(p)
725→		if trimmed != "" {
726→			result = append(result, trimmed)
727→		}
728→	}
729→	return result
730→}
